import time
import logging
import serial

logging.basicConfig(level=logging.INFO)
LOGGER = logging.getLogger("uart_client")

def open_port(device_path):
    """Open and return a configured serial port for the device."""
    # pyserial opens the UART link to the attached device
    return serial.Serial(device_path, baudrate=9600, timeout=1)

def read_reading(serial_port):
    """Read one line of data from the device and validate it."""
    # Strip whitespace and reject empty or malformed readings
    raw_line = serial_port.readline().decode("utf-8", "ignore").strip()
    if not raw_line:
        return None
    try:
        reading_value = float(raw_line)
        return reading_value
    except ValueError:
        LOGGER.warning("Invalid reading: %s", raw_line)
        return None

def main():
    """Continuously read and report readings from the device."""
    device_path = "/dev/ttyS0"
    serial_port = None
    try:
        serial_port = open_port(device_path)
        while True:
            reading_value = read_reading(serial_port)
            if reading_value is not None:
                print("Device reading:", reading_value)
            time.sleep(5)
    except serial.SerialException as serial_error:
        LOGGER.error("Device not found at %s: %s", device_path, serial_error)
    except KeyboardInterrupt:
        LOGGER.info("Stopping uart client")
    finally:
        # Always close the serial port to free the hardware
