from gpiozero import LED
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pins using BCM numbering
DEVICE_PINS = [4, 5, 6, 13, 17, 22, 27]

class DeviceController:
    """
    Controls multiple LEDs connected to specified GPIO pins.

    Provides methods for turning LEDs on and off, reading their current state,
    and managing the devices' lifecycle.
    """

    def __init__(self, pins):
        """
        Initializes the DeviceController with a list of GPIO pins.

        Args:
            pins (list): A list of integers representing the GPIO pins.

        Raises:
            ValueError: If any pin number is invalid.
        """
        self.devices = []
        try:
            for pin in pins:
                led = LED(pin)
                self.devices.append(led)
            logging.info("Device controller initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing device controller: {e}")
            raise

    def turn_on_all(self):
        """Turns on all controlled LEDs."""
        try:
            for device in self.devices:
                device.on()
            logging.debug("All devices turned ON.")
        except Exception as e:
            logging.error(f"Error turning on devices: {e}")

    def turn_off_all(self):
        """Turns off all controlled LEDs."""
        try:
            for device in self.devices:
                device.off()
            logging.debug("All devices turned OFF.")
        except Exception as e:
            logging.error(f"Error turning off devices: {e}")

    def read_all_states(self):
        """
        Reads the current state of all LEDs.

        Returns:
            list: A list of boolean values representing the state of each LED (True for on, False for off).
        """
        try:
            states = [device.is_lit for device in self.devices]
            logging.debug(f"Device states read: {states}")
            return states
        except Exception as e:
            logging.error(f"Error reading device states: {e}")
            return None

    def close_all(self):
        """Releases all GPIO resources."""
        try:
            for device in self.devices:
                device.close()
            logging.info("All devices closed.")
        except Exception as e:
            logging.error(f"Error closing devices: {e}")


def main():
    """Main function to demonstrate device control."""

    controller = None  # Initialize controller outside the try block
    try:
        controller = DeviceController(DEVICE_PINS)

        while True:
            controller.turn_on_all()
            states = controller.read_all_states()
            if states:
                print(f"States: {states}")
            time.sleep(0.01)

            controller.turn_off_all()
            states = controller.read_all_states()
            if states:
                print(f"States: {states}")
            time.sleep(0.01)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.critical(f"An unhandled error occurred: {e}")
    finally:
        if controller:
            controller.close_all()
        logging.info("Program exiting.")


if __name__ == "__main__":
    main()

