import time
import sys
from Adafruit_I2C import Adafruit_I2C

# I2C address of the ADS1015
ADS1015_ADDRESS = 0x48

# Register addresses for the ADS1015
ADS1015_REG_POINTER_CONVERT = 0x00
ADS1015_REG_POINTER_CONFIG = 0x01


class ADS1015:
    """Simplified ADS1015 ADC reader for Raspberry Pi."""

    def __init__(self, address=ADS1015_ADDRESS):
        """Initialize the ADC reader."""
        try:
            self.i2c = Adafruit_I2C(address)
        except Exception as e:
            print(f"Error initializing I2C: {e}")
            sys.exit(1)

    def read_channel(self, channel):
        """Read the analog value from the specified channel (0-3)."""
        if not 0 <= channel <= 3:
            raise ValueError("Invalid channel number. Must be between 0 and 3.")

        # Create configuration value
        config = 0x8583 | (channel << 12)  # Single-ended, 6.144V range, continuous mode

        # Start conversion
        try:
            self.i2c.writeList(ADS1015_REG_POINTER_CONFIG, [(config >> 8) & 0xFF, config & 0xFF])
        except Exception as e:
            print(f"Error writing to ADC: {e}")
            return None

        # Wait for conversion to complete (adjust delay as needed)
        time.sleep(0.1)

        # Read conversion result
        try:
            result = self.i2c.readList(ADS1015_REG_POINTER_CONVERT, 2)
        except Exception as e:
            print(f"Error reading from ADC: {e}")
            return None

        value = (result[0] << 8) | result[1]

        return value


