import time
import signal
import sys
from smbus2 import SMBus

# I2C address of the PCF8574 GPIO expander
PCF8574_ADDRESS = 0x20
# I2C bus number on the Raspberry Pi
I2C_BUS_NUMBER = 1


class GracefulExit:
    """Context manager to handle graceful exit on signals."""

    def __init__(self):
        self._original_handlers = {}
        self._signals_to_handle = [signal.SIGINT, signal.SIGTERM]

    def __enter__(self):
        # Store original signal handlers and set new ones
        for sig in self._signals_to_handle:
            self._original_handlers[sig] = signal.getsignal(sig)
            signal.signal(sig, self._handle_signal)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        # Restore original signal handlers
        for sig, handler in self._original_handlers.items():
            signal.signal(sig, handler)

    def _handle_signal(self, signum, frame):
        raise KeyboardInterrupt()


def read_pcf8574(i2c_bus, device_address):
    """Read a byte from the PCF8574."""
    try:
        return i2c_bus.read_byte(device_address)
    except Exception as e:
        print(f"Error reading from PCF8574: {e}")
        return None


def main():
    """Main function to read data from the PCF8574 and print it."""
    with GracefulExit():
        try:
            with SMBus(I2C_BUS_NUMBER) as i2c_bus:
                while True:
                    reading = read_pcf8574(i2c_bus, PCF8574_ADDRESS)
                    if reading is not None:
                        print(f"PCF8574 Reading: {reading}")
                    time.sleep(0.1)
        except FileNotFoundError:
            print("Error: I2C bus not found. Make sure I2C is enabled.")
            sys.exit(1)
        except Exception as e:
            print(f"An unexpected error occurred: {e}")
            sys.exit(1)


if __name__ == "__main__":
