import time
import json
import logging
import threading
import queue
import RPi.GPIO as GPIO

# Configure logging for the wearable device
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for the wearable sensor node
DHT_PIN = 4
MQTT_TOPIC = "wearable/sensor/data"
READ_INTERVAL_SECONDS = 5


class SensorReader:
    """Reads data from a simulated heart rate sensor."""

    def __init__(self):
        """Initializes the sensor reader."""
        self.last_heart_rate = 70  # Initial heart rate

    def read_sensor(self):
        """Simulates reading a heart rate sensor."""
        # Simulate heart rate fluctuations
        self.last_heart_rate += (time.time() % 10) - 5
        self.last_heart_rate = max(60, min(100, self.last_heart_rate))  # Clamp values
        return int(self.last_heart_rate)


class MessageQueue:
    """Manages a queue for publishing sensor data."""

    def __init__(self):
        """Initializes the message queue."""
        self.queue = queue.Queue()

    def enqueue(self, message):
        """Adds a message to the queue."""
        self.queue.put(message)

    def dequeue(self):
        """Removes and returns a message from the queue."""
        try:
            return self.queue.get(timeout=1)  # Wait up to 1 second
        except queue.Empty:
            return None


class MqttPublisher:
    """Publishes messages to an MQTT broker (simulated)."""

    def __init__(self, topic):
        """Initializes the MQTT publisher."""
        self.topic = topic

    def publish(self, message):
        """Simulates publishing a message to the MQTT broker."""
        logging.info(f"Published to {self.topic}: {message}")


def sensor_reading_task(sensor_reader, message_queue):
    """Continuously reads sensor data and enqueues it."""
    while True:
        try:
            heart_rate = sensor_reader.read_sensor()
            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            data = {"timestamp": timestamp, "heart_rate": heart_rate}
            message_queue.enqueue(json.dumps(data))
            time.sleep(READ_INTERVAL_SECONDS)
        except Exception as e:
            logging.error(f"Sensor reading error: {e}")
            time.sleep(READ_INTERVAL_SECONDS)


def mqtt_publishing_task(message_queue, mqtt_publisher):
    """Continuously dequeues messages and publishes them."""
    while True:
        try:
            message = message_queue.dequeue()
            if message:
                mqtt_publisher.publish(message)
        except Exception as e:
            logging.error(f"MQTT publishing error: {e}")


def main():
    """Main function to run the wearable sensor node."""
    try:
        # Initialize components
        sensor_reader = SensorReader()
        message_queue = MessageQueue()
        mqtt_publisher = MqttPublisher(MQTT_TOPIC)

        # Create and start threads
        sensor_thread = threading.Thread(target=sensor_reading_task, args=(sensor_reader, message_queue), daemon=True)
        mqtt_thread = threading.Thread(target=mqtt_publishing_task, args=(message_queue, mqtt_publisher), daemon=True)

        sensor_thread.start()
        mqtt_thread.start()

        # Keep the main thread alive
        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Exiting program.")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        logging.info("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

